class Solution {
public:
    vector<long long> powerUpdate(vector<int>& nums, int p, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        vector<long long> ans;
        long long cur = p;
        for (auto& q : queries) {
            nums.push_back(q[0]);
            sort(nums.begin(), nums.end());
            int x = nums[nums.size() - q[1]];
            cur = 1;
            long long base = p % MOD;
            int e = x;
            while (e > 0) {
                if (e & 1) cur = cur * base % MOD;
                base = base * base % MOD;
                e >>= 1;
            }
            ans.push_back(cur);
        }
        return ans;
    }
};

