class Solution {
    public long[] powerUpdate(int[] nums, int p, int[][] queries) {
        final long MOD = 1000000007L;
        List<Integer> list = new ArrayList<>();
        for (int v : nums) list.add(v);
        long[] ans = new long[queries.length];
        long cur = p;
        for (int i = 0; i < queries.length; i++) {
            list.add(queries[i][0]);
            Collections.sort(list);
            int x = list.get(list.size() - queries[i][1]);
            cur = modpow(cur, x, MOD);
            ans[i] = cur;
        }
        return ans;
    }
    private long modpow(long b, long e, long m) {
        long r = 1;
        b %= m;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }
}

