var powerUpdate = function(nums, p, queries) {
    const MOD = 1000000007n;
    nums.sort((a, b) => a - b);
    const ans = [];
    let cur = BigInt(p);
    for (const [val, k] of queries) {
        let lo = 0, hi = nums.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (nums[mid] <= val) lo = mid + 1; else hi = mid;
        }
        nums.splice(lo, 0, val);
        const x = BigInt(nums[nums.length - k]);
        let r = 1n, base = cur % MOD, e = x;
        while (e > 0n) {
            if (e & 1n) r = r * base % MOD;
            base = base * base % MOD;
            e >>= 1n;
        }
        cur = r;
        ans.push(Number(cur));
    }
    return ans;
};
